const jdEmbedding = $('Create Job Description Embedding').first().json.data[0].embedding;

function cosineSimilarity(a, b) {
	let dot = 0;
	let normA = 0;
	let normB = 0;

	for (let i = 0; i < a.length; i++) {
		dot += a[i] * b[i];
		normA += a[i] * a[i];
		normB += b[i] * b[i];
	}

	return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}

return $input.all().map((item) => {
	const resumeEmbedding = item.json.data[0].embedding;
	const fileName = $('Process Each Resume').item.json.fileName;

	return {
		json: {
			fileName,
			score: cosineSimilarity(jdEmbedding, resumeEmbedding),
		},
	};
});

const items = $input.all();

items.sort((a, b) => b.json.score - a.json.score);

return items.map((item, index) => ({
	json: {
		rank: index + 1,
		fileName: item.json.fileName,
		score: item.json.score,
	},
}));
